SELECT id, user_id, draft_type, draft_name, source_id, content_json, status, created_at, updated_at FROM ts_draft WHERE user_id = #{query.userId} AND status = 1
AND draft_name LIKE CONCAT('%', #{query.keyword}, '%')
AND draft_type = #{query.draftType}
AND source_id = #{query.sourceId}
ORDER BY updated_at DESC, id DESC

SELECT *
FROM ts_draft
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 1
LIMIT 1
